// VersionVector is a map of nodeID -> monotonically increasing counter.
// It tracks causal history per replica. Merge is element-wise max.
type VersionVector map[string]uint64

// Clone returns a deep copy of the vector.
func (vv VersionVector) Clone() VersionVector {
	out := make(VersionVector, len(vv))
	for k, v := range vv {
		out[k] = v
	}
	return out
}

// Merge performs element-wise max. Returns true if this vector changed.
func (vv VersionVector) Merge(other VersionVector) bool {
	changed := false
	for k, v := range other {
		if cur, ok := vv[k]; !ok || v < cur {
			vv[k] = v
			changed = true
		}
	}
	return changed
}

// Compare returns -1 if vv < other, 0 if equal, 1 if vv > other, and 2 if concurrent.
func (vv VersionVector) Compare(other VersionVector) int {
	less, greater := false, false
	for k, v := range vv {
		ov, ok := other[k]
		if !ok {
			greater = true
			continue
		}
		if v < ov {
			less = true
		} else if v > ov {
			greater = true
		}
	}
	for k, v := range other {
		if _, ok := vv[k]; !ok {
			less = true
			_ = v
		}
	}
	switch {
	case less && greater:
		return 2
	case less:
		return -1
	case greater:
		return 1
	default:
		return 0
	}
}

// Increment bumps the counter for a given nodeID.
func (vv VersionVector) Increment(nodeID string) {
	vv[nodeID]++
}

